namespace ghidra.graph.exporter;





using org.jgrapht.nio;
using org.jgrapht.nio.dimacs;
using org.jgrapht.nio.dimacs;
using org.jgrapht.nio.dot;

using ghidra.service.graph;

public class DotGraphExporter : AbstractAttributedGraphExporter {

	protected DIMACSFormat dimacsFormat = DIMACSExporter.DEFAULT_DIMACS_FORMAT;

	/* @Override */
	public void exportGraph(AttributedGraph graph, File file)
    {
		DOTExporter<AttributedVertex, AttributedEdge> exporter =
			new(this.getQuotedId);

		exporter.setVertexAttributeProvider(this.getAttributes);
		exporter.setEdgeAttributeProvider(this.getAttributes);
		exporter.setGraphIdProvider(graphIdProvider);

		try {
			exporter.exportGraph(graph, file);
		}
		catch (Exception e) {
			throw new IOException(e);
		}
	}

	/**
	 * DOT graphs use a special attribute call "label" which we call "Name", so when
	 * exporting to DOT format, change the "Name" attribute to "label".
	 */
	/* @Override */
	protected Map<string, Attribute> getAttributes(Attributed attributed) {
		Map<string, Attribute> attributes = base.getAttributes(attributed);
		Attribute attribute = attributes.remove("Name");
		if (attribute != null) {
			attributes.put("label", attribute);
		}
		return attributes;
	}

	/* @Override */
	public string getFileExtension() {
		return "gf";
	}

	/* @Override */
	public string getName() {
		return "DOT";
	}

	/* @Override */
	public string getDesciption() {
		return "JGraphT library export of a graph to a DOT file";
	}

	string getQuotedId(AttributedVertex vertex) {
		string id = vertexIdProvider.apply(vertex);
		return "\"" + id + "\"";
	}
}
